use NpmGateway\Configuration\ProtectedPrincipalConfig;use NpmGateway\Contracts\StorageAdapterInterface;use NpmGateway\Database\DatabaseProfiles;use NpmGateway\Database\MySqlConnectionFactory;use NpmGateway\Database\MySqlInitializationTransaction;use NpmGateway\Http\AuthenticatedRequestContext;use NpmGateway\Repositories\AuditRepository;use NpmGateway\Repositories\CreditCardPurchaseRepository;use NpmGateway\Repositories\PropertyAccessRepository;use NpmGateway\Repositories\StorageObjectRepository;use NpmGateway\Services\AuditService;use NpmGateway\Services\CompanyNoticeZipValidator;use NpmGateway\Services\CreditCardPurchaseService;use NpmGateway\Services\CreditCardPurchaseValidator;use NpmGateway\Services\GatewayStorageService;use NpmGateway\Services\PropertyAccessService;use NpmGateway\Services\StorageConfiguration;use NpmGateway\Services\StorageObjectKeyGenerator;use NpmGateway\Services\StorageUploadValidator;use NpmGateway\Support\PublicIdGenerator;use NpmGateway\Support\SystemClock;use NpmGateway\ValueObjects\AuthenticatedUser;use NpmGateway\ValueObjects\CommunityActionContext;use NpmGateway\ValueObjects\StorageProviderHead;use NpmGateway\ValueObjects\StorageProviderObject;use PHPUnit\Framework\TestCase;
final class CreditCardPurchasesIntegrationTest extends TestCase{
 private mysqli $db;private array $ids=[];private ?string $tmp=null;
 protected function setUp():void{$root=dirname(__DIR__,2);$p=DatabaseProfiles::load('migration',$root);if(($p['database']??'')!=='npmgateway_test')self::markTestSkipped('Credit Card Purchases certification requires npmgateway_test.');$this->db=MySqlConnectionFactory::connect($p);}
 protected function tearDown():void{if(!isset($this->db))return;$u=(int)($this->ids['user']??0);$e1=(int)($this->ids['manager_employee']??0);$e2=(int)($this->ids['maintenance_employee']??0);$p=(int)($this->ids['property']??0);if($u){$this->db->query("DELETE FROM audit_logs WHERE user_id={$u} OR entity_public_id='".$this->db->real_escape_string((string)($this->ids['purchase_public']??''))."'");$this->db->query("DELETE FROM credit_card_purchase_history WHERE actor_user_id={$u}");$this->db->query("DELETE FROM credit_card_purchase_receipts WHERE uploaded_by_user_id={$u}");$this->db->query("DELETE FROM credit_card_purchases WHERE submitted_by_user_id={$u}");$this->db->query("DELETE FROM storage_objects WHERE uploaded_by_user_id={$u}");$this->db->query("DELETE FROM user_property_access WHERE user_id={$u}");}$this->db->query('DELETE FROM employee_property_assignments WHERE employee_id IN ('.$e1.','.$e2.')');if($u)$this->db->query("DELETE FROM users WHERE id={$u}");$this->db->query('DELETE FROM employees WHERE id IN ('.$e1.','.$e2.')');if($p)$this->db->query("DELETE FROM properties WHERE id={$p}");$this->db->close();if($this->tmp&&is_file($this->tmp))unlink($this->tmp);}
 public function testPropertyScopedMissingAndAttachedPurchasesUseTrustedIdentitiesAndFakeStorage():void{$ids=new PublicIdGenerator();$propPublic=$ids->generate();$propId=random_int(880000,889999);$email='cc'.$propId.'@example.test';$s=$this->db->prepare("INSERT INTO properties(public_id,prop_id,property_code,slug,display_name,status,manager_email,address_line_1,city,state,postal_code,timezone) VALUES(?,?,'QZ',?,'Credit Card Test','active',?,'1 Test Way','Test','PA','18503','America/New_York')");$slug='cc-test-'.$propId;$s->bind_param('siss',$propPublic,$propId,$slug,$email);$s->execute();$property=(int)$this->db->insert_id;$s->close();$this->ids['property']=$property;$manager=$this->employee($ids,'Manager','corporate');$maintenance=$this->employee($ids,'Maintenance','maintenance');$this->ids['manager_employee']=$manager['id'];$this->ids['maintenance_employee']=$maintenance['id'];$hash=password_hash('Disposable-123!',PASSWORD_DEFAULT);$userPublic=$ids->generate();$username='ccmanager'.$propId;$s=$this->db->prepare("INSERT INTO users(public_id,employee_id,username,password_hash,status) VALUES(?,?,?,?,'active')");$s->bind_param('siss',$userPublic,$manager['id'],$username,$hash);$s->execute();$userId=(int)$this->db->insert_id;$s->close();$this->ids['user']=$userId;foreach([$manager['id'],$maintenance['id']] as $employee){$public=$ids->generate();$s=$this->db->prepare("INSERT INTO employee_property_assignments(public_id,employee_id,property_id,assignment_type,is_primary,starts_on,created_by) VALUES(?,?,?,'maintenance',1,'2026-01-01',?)");$s->bind_param('siii',$public,$employee,$property,$userId);$s->execute();$s->close();}$accessPublic=$ids->generate();$s=$this->db->prepare('INSERT INTO user_property_access(public_id,user_id,property_id,granted_by_user_id,granted_at) VALUES(?,?,?,?,NOW())');$s->bind_param('siii',$accessPublic,$userId,$property,$userId);$s->execute();$s->close();$user=new AuthenticatedUser($userId,$manager['id'],$userPublic,$manager['public'],'ccmanager','Manager Test');$context=new CommunityActionContext($user,$userId,$userPublic,$manager['id'],$manager['public'],$property,$propPublic,$slug,'QZ','Credit Card Test',true);$fake=new CreditCardFakeStorage();$objects=new StorageObjectRepository($this->db);$clock=new SystemClock(new DateTimeZone('UTC'));$audit=new AuditService(new AuditRepository($this->db),$ids);$gateway=new GatewayStorageService(new StorageConfiguration('https://storage.example.test','us-east-1','test','key','secret','receipts/','images/','test/'),$fake,$objects,new StorageObjectKeyGenerator(),new StorageUploadValidator(new CompanyNoticeZipValidator()),$ids,$clock,$audit);$propertyAccess=new PropertyAccessService(new PropertyAccessRepository($this->db),new MySqlInitializationTransaction($this->db),$audit,$ids,$clock);$repo=new CreditCardPurchaseRepository($this->db);$service=new CreditCardPurchaseService($repo,new CreditCardPurchaseValidator(),new MySqlInitializationTransaction($this->db),$ids,$clock,$audit,$propertyAccess,$gateway,$objects);$base=['card_last_four'=>'0425','purchase_date'=>(new DateTimeImmutable())->format('Y-m-d'),'amount'=>'166.26','purchased_by_employee_public_id'=>$maintenance['public'],'vendor'=>'Short & Paulk','description'=>'Maintenance materials.'];$missing=$service->post($context,$base+['receipt_missing'=>'1','missing_receipt_reason'=>'Vendor printer was unavailable.'],[]);$one=$repo->detail($missing['public_id'],$property);self::assertSame($userId,(int)$one['submitted_by_user_id']);self::assertSame($maintenance['id'],(int)$one['purchased_by_employee_id']);self::assertSame('0425',$one['card_last_four']);self::assertSame('166.26',$one['amount']);self::assertSame('missing',$one['receipt_status']);self::assertCount(1,$one['history']);$this->tmp=tempnam(sys_get_temp_dir(),'ccr');file_put_contents($this->tmp,"%PDF-1.4\n%%EOF");$file=['error'=>UPLOAD_ERR_OK,'tmp_name'=>$this->tmp,'name'=>'receipt.pdf','size'=>filesize($this->tmp),'type'=>'text/plain'];$attached=$service->post($context,$base+['card_last_four'=>'0007'],['receipt'=>$file]);$two=$repo->detail($attached['public_id'],$property);$this->ids['purchase_public']=$attached['public_id'];self::assertSame('attached',$two['receipt_status']);self::assertNotEmpty($two['storage_public_id']);self::assertSame(1,$fake->puts);self::assertSame(2,(int)$this->db->query("SELECT COUNT(*) FROM credit_card_purchases WHERE property_id={$property}")->fetch_row()[0]);$summary=$repo->summary($property,'','');self::assertSame(2,$summary['total']);self::assertSame('332.52',$summary['total_posted']);self::assertSame(1,$summary['attached']);self::assertSame(1,$summary['missing']);$attachedSummary=$repo->summary($property,'','attached');self::assertSame(1,$attachedSummary['total']);self::assertSame('166.26',$attachedSummary['total_posted']);$csrfState=[];$flashState=[];$tools=new class implements \NpmGateway\Contracts\CorporateToolsProviderInterface{public function tools(AuthenticatedRequestContext $context):array{return [];}};$controller=new \NpmGateway\Http\Controllers\CreditCardPurchaseController(new \NpmGateway\Services\CommunityActionContextResolver($propertyAccess),$service,$gateway,$tools,new \NpmGateway\Security\CsrfService($csrfState),new \NpmGateway\Support\FlashSession($flashState),dirname(__DIR__,2).'/resources/views');$requestContext=new AuthenticatedRequestContext($user,'test-session');$view=$controller->viewReceipt($slug,$attached['public_id'],$two['receipt_public_id'],$requestContext);self::assertSame(200,$view->status);self::assertSame('application/pdf',$view->headers['Content-Type']);self::assertStringStartsWith('inline',$view->headers['Content-Disposition']);self::assertSame('private, no-store',$view->headers['Cache-Control']);self::assertSame('nosniff',$view->headers['X-Content-Type-Options']);self::assertSame("default-src 'none'; frame-ancestors 'self'",$view->headers['Content-Security-Policy']);self::assertTrue(is_resource($view->stream));fclose($view->stream);$download=$controller->downloadReceipt($slug,$attached['public_id'],$two['receipt_public_id'],$requestContext);self::assertSame(200,$download->status);self::assertStringStartsWith('attachment',$download->headers['Content-Disposition']);fclose($download->stream);self::assertSame(404,$controller->viewReceipt($slug,$attached['public_id'],str_repeat('Z',26),$requestContext)->status);$this->db->query("DELETE FROM user_property_access WHERE user_id={$userId} AND property_id={$property}");self::assertSame(403,$controller->viewReceipt($slug,$attached['public_id'],$two['receipt_public_id'],$requestContext)->status);self::assertSame(0,(int)$this->db->query("SELECT COUNT(*) FROM notifications WHERE source_entity_public_id IN ('{$missing['public_id']}','{$attached['public_id']}')")->fetch_row()[0]);}
 private function employee(PublicIdGenerator $ids,string $first,string $class):array{$public=$ids->generate();$number='NPM'.random_int(800000,879999);$s=$this->db->prepare("INSERT INTO employees(public_id,employee_number,employee_class,first_name,last_name,job_title,employment_status,start_date) VALUES(?,?,?,?,'Purchase Test','Test','active','2026-01-01')");$s->bind_param('ssss',$public,$number,$class,$first);$s->execute();$id=(int)$this->db->insert_id;$s->close();return ['id'=>$id,'public'=>$public];}}
final class CreditCardFakeStorage implements StorageAdapterInterface{public int $puts=0;private array $objects=[];public function put(string $container,string $key,mixed $stream,int $bytes,string $mime,string $sha):StorageProviderObject{$this->puts++;$this->objects[$key]=[$bytes,$mime,$sha];return new StorageProviderObject($bytes,$mime);}public function head(string $container,string $key):StorageProviderHead{[$b,$m,$s]=$this->objects[$key];return new StorageProviderHead($b,$m,null,$s);}public function openReadStream(string $container,string $key):mixed{$h=fopen('php://temp','r+');return $h;}public function exists(string $container,string $key):bool{return isset($this->objects[$key]);}public function delete(string $container,string $key):void{unset($this->objects[$key]);}public function listPrefix(string $container,string $prefix):array{return [];}}
